/// <summary>
/// Controller class for transfer picking list generation service
/// </summary>
class METTransferPickingListGenerationController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new METTransferPickingListGenerationController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmLoadFromSysLastValue(false); // parameters are set via code

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METTransferPickingListGenerationService), methodstr(METTransferPickingListGenerationService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>Main method</summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METTransferPickingListGenerationContract    dataContract;
        METTransferPickingListGenerationController  controller;
        FormRun                                     formRun;
        Map                                         transferMap;
        MapEnumerator                               mapEnumerator;
        MapEnumerator                               selectedRecordsEnumerator;
        container                                   ocsCodeCon, transferOrderOSCCon;
        InventTransferId                            transferId;
        Map                                         selectedMap;
        InventTransferTable                         inventTransferTable;
        METOSCCode                                  oscCode;

        transferMap                         = new Map(Types::String, Types::Container);
        formRun                             = _args.caller();
        selectedMap                         = formRun.getSelectedRecordsMap();
        selectedRecordsEnumerator           = selectedMap.getEnumerator();

        while (selectedRecordsEnumerator.moveNext())
        {
            inventTransferTable = inventTransferTable::find(selectedRecordsEnumerator.currentValue());
            oscCode = METTransferPickingListGenerationController::getOSCCode(inventTransferTable.TransferId);
            
            if (!transferMap.exists(inventTransferTable.TransferId))
            {
                transferMap.insert(inventTransferTable.TransferId, [oscCode]);
            }
            else
            {
                ocsCodeCon          = transferMap.lookup(inventTransferTable.TransferId);
                if(!conFind(ocsCodeCon, oscCode))
                {
                    ocsCodeCon      = conIns(ocsCodeCon, conLen(ocsCodeCon) + 1, oscCode);
                    transferMap.remove(inventTransferTable.TransferId);
                    transferMap.insert(inventTransferTable.TransferId, ocsCodeCon);
                }
            }
        }

        mapEnumerator               = transferMap.getEnumerator();

        while (mapEnumerator.moveNext())
        {
            transferId              = mapEnumerator.currentKey();
            ocsCodeCon              = mapEnumerator.currentValue();
            ocsCodeCon              = conIns(ocsCodeCon, 1, transferId);
            transferOrderOSCCon     = conIns(transferOrderOSCCon, conLen(transferOrderOSCCon) + 1, ocsCodeCon);
        }

        if (conLen(transferOrderOSCCon))
        {
            controller              = METTransferPickingListGenerationController::construct(_args);
            dataContract            = controller.getDataContractObject();
            dataContract.parmTransferOrderList(transferOrderOSCCon);
            controller.parmShowDialog(false);
            controller.startOperation();
            Info("@MET:MetPickingListGenerationBatchCreated");            
        }
        else
        {
            warning("@MET:NoTransferOrderToProcess");
        }
    }

/// <summary>
/// Description
/// </summary>
/// <returns>Generate purchase orders</returns>
public ClassDescription defaultCaption()
{
    return "@MET:MetPickingListGeneration";
}

    /// <summary>
    /// Method to ger OSCCode
    /// </summary>
    /// <param name = "_inventTransferId">InventTransferId reference</param>
    /// <returns>METOSCCode</returns>
    public static METOSCCode getOSCCode(InventTransferId       _inventTransferId)
    {
        ReqItemTable        reqItemTable;
        METReqItemTable     metReqItemTable;
        InventTransferLine  inventTransferLine;

        select firstonly metReqItemTable
            exists join reqItemTable
                where reqItemTable.RecId == metReqItemTable.RefRecId
            exists join inventTransferLine
                where inventTransferLine.ItemId == reqItemTable.ItemId  &&
            inventTransferLine.TransferId == _inventTransferId;

        return metReqItemTable.OSCCode; 
    }
